"""PL-01 step 2: keep the usable rows, sorted by (date, ticker)."""

from __future__ import annotations

from collections.abc import Sequence

from mdata.types import RawRow


def validate_rows(rows: Sequence[RawRow], tickers: Sequence[str] | None = None) -> list[RawRow]:
    """The rows with a positive close, the later of each (date, ticker), sorted by (date, ticker).

    Narrowed to `tickers` when given; a requested ticker with no usable row is a `KeyError`.
    """
    latest = {
        (row.date, row.ticker): row for row in rows if row.close is not None and row.close > 0
    }
    kept = list(latest.values())
    if tickers is not None:
        missing = [ticker for ticker in tickers if all(row.ticker != ticker for row in kept)]
        if missing:
            raise KeyError(f"no usable rows for tickers: {', '.join(missing)}")
        wanted = set(tickers)
        kept = [row for row in kept if row.ticker in wanted]
    return sorted(kept, key=lambda row: (row.date, row.ticker))

